// The "Development" tab: the story of how the project was built, in first person, as sections of paragraphs,
// lists, figures (the experiment plots, in public/development/) and charts (numbers in devCharts.ts).
// Every piece of text is in both site languages. `**bold**` inside a paragraph is rendered bold.

export type L = { en: string; ko: string };
export type ChartId = "rMarginSweep" | "baselineVsApp" | "finetunePer";
export type Block =
  | { kind: "p"; text: L }
  | { kind: "list"; items: L[] }
  | { kind: "figure"; src: string; width: number; height: number; alt: L; caption: L }
  | { kind: "chart"; chart: ChartId; caption: L };
export type Section = { id: string; heading: L; blocks: Block[] };

const P = (en: string, ko: string): Block => ({ kind: "p", text: { en, ko } });
const LIST = (...items: [string, string][]): Block => ({ kind: "list", items: items.map(([en, ko]) => ({ en, ko })) });
const FIG = (src: string, width: number, height: number, alt: [string, string], caption: [string, string]): Block => ({
  kind: "figure", src, width, height, alt: { en: alt[0], ko: alt[1] }, caption: { en: caption[0], ko: caption[1] },
});
const CHART = (chart: ChartId, en: string, ko: string): Block => ({ kind: "chart", chart, caption: { en, ko } });

